-- Service catalog: what the user sells. finding_codes/finding_categories map audit evidence to a service;
-- a trailing * in a code is a prefix wildcard (cro:* matches cro:abc). The id is the key for seeded rows.
CREATE TABLE services (
  id TEXT PRIMARY KEY,
  key TEXT NOT NULL UNIQUE,
  name TEXT NOT NULL,
  category TEXT NOT NULL,
  summary TEXT NOT NULL DEFAULT '',
  deliverables TEXT NOT NULL DEFAULT '[]',
  prerequisites TEXT NOT NULL DEFAULT '[]',
  first_engagement TEXT,
  finding_codes TEXT NOT NULL DEFAULT '[]',
  finding_categories TEXT NOT NULL DEFAULT '[]',
  is_specialty INTEGER NOT NULL DEFAULT 0,
  active INTEGER NOT NULL DEFAULT 1,
  sort INTEGER NOT NULL DEFAULT 0
);

